awards.sql:
SELECT COUNT(DISTINCT award_id) AS awards
FROM fact_transactions
WHERE fiscal_year = :fiscal_year;

recipients.sql:
SELECT COUNT(DISTINCT recipient_id) AS recipients
FROM fact_transactions
WHERE fiscal_year = :fiscal_year;

hhi.sql:
WITH suppliers AS (
  SELECT recipient_id, GREATEST(SUM(obligation), 0) AS positive
  FROM fact_transactions WHERE fiscal_year = :fiscal_year
  GROUP BY recipient_id
), shares AS (
  SELECT positive / SUM(positive) OVER () AS share FROM suppliers
)
SELECT 10000 * SUM(share * share) AS hhi FROM shares;
